INSERT INTO "Schedule" ("id", "executiveId", "date", "startTime", "endTime", "mission", "location", "agency", "dressCode", "status", "createdAt", "updatedAt") VALUES ('618388aa-5a44-4750-9a8c-a2efe86ebc8b', 'a4482f90-cdb7-488d-8d40-8f38d09a8f75', '2026-06-09T17:00:00.000Z', '09:30', NULL, 'กิจกรรมจิตอาสาก่อสร้างฝายชะลอน้ำ ตามโครงการหนึ่งความดี ล้านความรัก ภูมิใจภักดิ์พระพันปีหลวง', 'บริเวณป่าชุมชนบ้านทรายทอง หมู่ ๑๖ ต.ป่าสัก อ.เมืองปทุมธานี', 'อ.เมืองปทุมธานี', 'ชุดจิตอาสาพระราชทาน เสื้อยืดคอปกสีดำ หมวกสีฟ้า ผ้าพันคอสีเหลือง', 'ACTIVE', '2026-09-04T11:42:58.904Z', '2026-09-04T11:42:58.904Z');
INSERT INTO "Schedule" ("id", "executiveId", "date", "startTime", "endTime", "mission", "location", "agency", "dressCode", "status", "createdAt", "updatedAt") VALUES ('4dd7a0fc-12ca-409c-a25e-c250b9628c79', 'a4482f90-cdb7-488d-8d40-8f38d09a8f75', '2026-06-09T17:00:00.000Z', '13:30', NULL, 'ร่วมตรวจเยี่ยมโรงงานอุตสาหกรรมในจังหวัดปทุมธานี ประจำเดือนมิถุนายน ๒๕๖๙', 'บริษัท ต้าปัง จำกัด ตำบลหนองหนาม อำเภอเมืองปทุมธานี', 'อุตสาหกรรมจังหวัด', 'ชุดสุภาพ', 'ACTIVE', '2026-09-04T11:42:58.904Z', '2026-09-04T11:42:58.904Z');
